<template><AppFrame><section class="page-heading mb-6"><div><p class="eyebrow">ACTIVOS</p><h1 class="text-h4 font-weight-bold">Máquinas</h1></div><v-btn color="primary" prepend-icon="mdi-plus" @click="openCreate">Nueva máquina</v-btn></section><v-alert v-if="error" type="error" variant="tonal" class="mb-3">{{ error }}</v-alert><v-card class="panel" elevation="0" rounded="xl"><v-data-table :headers="headers" :items="machines" :loading="loading"><template #item.estado="{item}"><v-chip size="small" :color="item.estado === 'FUERA_SERVICIO' ? 'error' : item.estado === 'MANTENIMIENTO' ? 'warning' : 'success'" variant="tonal">{{ item.estado }}</v-chip></template><template #item.actions="{item}"><v-btn icon="mdi-pencil" variant="text" @click="edit(item)"/><v-btn icon="mdi-delete" color="error" variant="text" @click="remove(item.id)"/></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="640"><v-card rounded="xl" :title="form.id ? 'Editar máquina' : 'Nueva máquina'"><v-card-text><v-text-field v-model="form.codigo" label="Código"/><v-text-field v-model="form.nombre" label="Nombre"/><v-text-field v-model="form.ubicacion" label="Ubicación"/><v-select v-model="form.estado" :items="states" label="Estado"/><v-select v-model="form.frecuencia_mantenimiento" :items="['diario','semanal','mensual']" label="Frecuencia"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">Cancelar</v-btn><v-btn color="primary" @click="save">Guardar</v-btn></v-card-actions></v-card></v-dialog></AppFrame></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import AppFrame from '@/components/AppFrame.vue';import api from '@/services/api';const machines=ref<any[]>([]),loading=ref(false),dialog=ref(false),error=ref('');const states=['OPERATIVA','MANTENIMIENTO','FUERA_SERVICIO'];const form=reactive<any>({id:'',codigo:'',nombre:'',ubicacion:'',estado:'OPERATIVA',frecuencia_mantenimiento:'mensual'});const headers=[{title:'Código',key:'codigo'},{title:'Máquina',key:'nombre'},{title:'Ubicación',key:'ubicacion'},{title:'Estado',key:'estado'},{title:'Frecuencia',key:'frecuencia_mantenimiento'},{title:'',key:'actions'}];async function load(){loading.value=true;try{machines.value=(await api.get('/admin/maquinas')).data}finally{loading.value=false}}function openCreate(){Object.assign(form,{id:'',codigo:'',nombre:'',ubicacion:'',estado:'OPERATIVA',frecuencia_mantenimiento:'mensual'});dialog.value=true}function edit(x:any){Object.assign(form,x);dialog.value=true}async function save(){try{form.id?await api.put(`/admin/maquinas/${form.id}`,form):await api.post('/admin/maquinas',form);dialog.value=false;load()}catch(e:any){error.value=e.response?.data?.error??'No se pudo guardar'}}async function remove(id:string){if(confirm('¿Eliminar máquina?')){await api.delete(`/admin/maquinas/${id}`);load()}}onMounted(load)</script><style scoped>.page-heading{display:flex;justify-content:space-between;align-items:center}.eyebrow{color:#1976d2;font-weight:700;letter-spacing:.14em}.panel{border:1px solid #e5e7eb}</style>
